package net.civeira.phylax.feature.template.templateasset.application.usecase.update;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.template.template.domain.TemplateReference;
import net.civeira.phylax.feature.template.templateasset.domain.TemplateAssetChangeSet;

class TemplateAssetUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the template asset input values are kept when converted to a change set and back")
  void test_template_asset_update_input_change_set_round_trip() {
    TemplateAssetUpdateInput input = TemplateAssetUpdateInput.builder().uid("one")
        .template(TemplateReference.of("one")).tenant(TenantReference.of("one")).code("one")
        .type("one").content("file_1").enabled(true).version(1).build();
    TemplateAssetChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    TemplateAssetUpdateInput copy = TemplateAssetUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTemplate().isPresent(),
        "template must be assigned by the builder");
    Assertions.assertEquals(input.getTemplate(), copy.getTemplate(),
        "template must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getCode().isPresent(), "code must be assigned by the builder");
    Assertions.assertEquals(input.getCode(), copy.getCode(),
        "code must survive the change set round trip");
    Assertions.assertTrue(input.getType().isPresent(), "type must be assigned by the builder");
    Assertions.assertEquals(input.getType(), copy.getType(),
        "type must survive the change set round trip");
    Assertions.assertTrue(input.getContent().isPresent(),
        "content must be assigned by the builder");
    Assertions.assertEquals(input.getContent(), copy.getContent(),
        "content must survive the change set round trip");
    Assertions.assertTrue(input.getEnabled().isPresent(),
        "enabled must be assigned by the builder");
    Assertions.assertEquals(input.getEnabled(), copy.getEnabled(),
        "enabled must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the template asset input builder can generate a new identifier")
  void test_template_asset_update_input_new_uid() {
    TemplateAssetUpdateInput input = TemplateAssetUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        TemplateAssetUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the template asset input starts empty and the setters assign values")
  void test_template_asset_update_input_setters() {
    TemplateAssetUpdateInput empty = TemplateAssetUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTemplate().isEmpty(), "template must be empty by default");
    Assertions.assertSame(empty, empty.setTemplate(TemplateReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTemplate().isPresent(),
        "template must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getCode().isEmpty(), "code must be empty by default");
    Assertions.assertSame(empty, empty.setCode("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getCode().isPresent(), "code must be assigned by the setter");
    Assertions.assertTrue(empty.getType().isEmpty(), "type must be empty by default");
    Assertions.assertSame(empty, empty.setType("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getType().isPresent(), "type must be assigned by the setter");
    Assertions.assertTrue(empty.getContent().isEmpty(), "content must be empty by default");
    Assertions.assertSame(empty, empty.setContent("file_1"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getContent().isPresent(), "content must be assigned by the setter");
    Assertions.assertTrue(empty.getEnabled().isEmpty(), "enabled must be empty by default");
    Assertions.assertSame(empty, empty.setEnabled(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEnabled().isPresent(), "enabled must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
